<script setup lang="ts">
import { Boxes, CircleDollarSign, PackageCheck, TrendingUp, Users } from 'lucide-vue-next'
import { computed, onMounted, ref } from 'vue'
import ExportButtons from '@/components/ui/ExportButtons.vue'
import StatusBadge from '@/components/ui/StatusBadge.vue'
import { catalogService } from '@/services/catalog.service'
import { ordersService } from '@/services/orders.service'
import { profilesService } from '@/services/profiles.service'
import type { Pedido, Producto } from '@/types/database.types'
import { formatCurrency, formatDate } from '@/utils/formatters'
const products = ref<Producto[]>([]); const orders = ref<Pedido[]>([]); const customers = ref(0); const loading = ref(true)
const revenue = computed(() => orders.value.filter((order) => ['pagado', 'enviado', 'entregado'].includes(order.estado)).reduce((sum, order) => sum + Number(order.total), 0))
const pending = computed(() => orders.value.filter((order) => order.estado === 'pendiente').length)
const exportRows = computed(() => orders.value.map((order) => [order.id, `${order.perfiles?.nombre ?? ''} ${order.perfiles?.apellido ?? ''}`.trim(), formatDate(order.creado_en), Number(order.total), order.estado]))
onMounted(async () => { try { const [productData, orderData, profileData] = await Promise.all([catalogService.listProducts(), ordersService.listOrders(), profilesService.list()]); products.value = productData; orders.value = orderData; customers.value = profileData.filter((profile) => profile.rol === 'cliente').length } finally { loading.value = false } })
</script>
<template><div><div class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h2 class="page-title">Resumen del negocio</h2><p class="page-copy">Una vista rápida del rendimiento de tu tienda.</p></div><ExportButtons title="Resumen de pedidos" file-name="resumen-pedidos" :headers="['Pedido', 'Cliente', 'Fecha', 'Total (CRC)', 'Estado']" :rows="exportRows" /></div><div class="mt-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div v-for="metric in [{ label: 'Ventas registradas', value: formatCurrency(revenue), icon: CircleDollarSign, color: 'bg-emerald-100 text-emerald-700' }, { label: 'Pedidos pendientes', value: pending, icon: PackageCheck, color: 'bg-amber-100 text-amber-700' }, { label: 'Productos', value: products.length, icon: Boxes, color: 'bg-blue-100 text-blue-700' }, { label: 'Clientes', value: customers, icon: Users, color: 'bg-violet-100 text-violet-700' }]" :key="metric.label" class="card p-5"><div class="flex items-center justify-between"><div><p class="text-sm font-semibold text-slate-500">{{ metric.label }}</p><p class="mt-2 text-2xl font-bold text-ink">{{ loading ? '—' : metric.value }}</p></div><div class="rounded-xl p-3" :class="metric.color"><component :is="metric.icon" class="size-6" /></div></div></div></div><div class="mt-7 grid gap-6 xl:grid-cols-[1.5fr_1fr]"><section class="card overflow-hidden"><header class="flex items-center justify-between border-b border-slate-100 p-5"><div><h3 class="font-bold text-ink">Pedidos recientes</h3><p class="text-sm text-slate-500">Últimos movimientos</p></div><RouterLink to="/admin/pedidos" class="text-sm font-semibold text-brand-700">Ver todos</RouterLink></header><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Fecha</th><th>Total</th><th>Estado</th></tr></thead><tbody><tr v-for="order in orders.slice(0, 6)" :key="order.id"><td class="font-semibold">#{{ order.id }}</td><td>{{ order.perfiles?.nombre }} {{ order.perfiles?.apellido }}</td><td class="text-sm text-slate-500">{{ formatDate(order.creado_en) }}</td><td class="font-semibold">{{ formatCurrency(order.total) }}</td><td><StatusBadge :value="order.estado" /></td></tr><tr v-if="!orders.length && !loading"><td colspan="5" class="text-center text-slate-500">Aún no hay pedidos.</td></tr></tbody></table></div></section><section class="card p-5"><div class="flex items-center gap-3"><div class="rounded-xl bg-brand-100 p-3 text-brand-700"><TrendingUp class="size-6" /></div><div><h3 class="font-bold text-ink">Inventario bajo</h3><p class="text-sm text-slate-500">Productos con 5 unidades o menos</p></div></div><div class="mt-5 space-y-3"><div v-for="product in products.filter((item) => item.stock <= 5).slice(0, 7)" :key="product.id" class="flex items-center justify-between rounded-xl bg-slate-50 p-3"><div><p class="font-semibold text-slate-800">{{ product.nombre }}</p><p class="text-sm text-slate-500">{{ product.categorias?.nombre }}</p></div><span class="rounded-lg px-2.5 py-1 text-sm font-bold" :class="product.stock === 0 ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'">{{ product.stock }}</span></div><p v-if="!products.some((product) => product.stock <= 5)" class="py-8 text-center text-slate-500">El inventario está saludable.</p></div></section></div></div></template>
